<script setup lang="ts">
import { onUnmounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { api } from './api'
import { privateKeyFileReader, maxPrivateKeyBytes } from './privateKeyFile'
import { errorMessage, requestKey, type Settings, type Preview, type Job } from './monitoring'
const props = defineProps<{ modelValue: boolean; nodeId: string }>(), emit = defineEmits<{ 'update:modelValue': [boolean]; saved: [] }>()
const router = useRouter(), settings = ref<Settings>(), error = ref(''), busy = ref(false), preview = ref<Preview>()
const form = reactive({ id: '', name: '', host: '', enabled: true, mode: 'native', port: 22, auth: 'key', key: '', keySource: 'path', keyContent: '', keyConfigured: false, password: '', override: false, roots: '', extensions: '', excludes: '' })
const reading=ref(false), fileInput=ref<HTMLInputElement>()
let dialogVersion=0, draftVersion=0
watch(form,()=>{draftVersion++;preview.value=undefined},{deep:true,flush:'sync'})
const keyReader=privateKeyFileReader(value=>{form.keyContent=value;preview.value=undefined;error.value=''},message=>{error.value=message},value=>{reading.value=value})
function filesSelected(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';if(files.length&&!busy.value)void keyReader.read(files)}
function dropped(event:DragEvent){if(!busy.value)void keyReader.read(Array.from(event.dataTransfer?.files||[]))}
function keySourceChanged(){keyReader.cancel();form.keyContent='';preview.value=undefined;error.value=''}
watch(()=>form.auth,()=>{keyReader.cancel();form.keyContent='';preview.value=undefined})
onUnmounted(()=>{dialogVersion++;keyReader.cancel();form.keyContent=''})
watch(() => props.modelValue, async value => { const current=++dialogVersion;keyReader.cancel();form.keyContent='';if (!value) return; error.value = ''; preview.value = undefined; try { const loaded=await api<Settings>('/api/settings'); if(current!==dialogVersion||!props.modelValue)return;settings.value=loaded;const nodes = (settings.value.values.nodes || []) as Record<string, unknown>[]; const n = nodes.find(n => n.id === props.nodeId); const effective = settings.value.effective_nodes.find(n => n.id === props.nodeId); const ssh = {...((effective?.ssh || {}) as Record<string,unknown>),...((n?.ssh || {}) as Record<string, unknown>)}, monitor = (n?.monitor || {}) as Record<string, unknown>; Object.assign(form, { id: n?.id || '', name: n?.name || '', host: n?.host || '', enabled: n?.enabled ?? true, mode: ((effective?.deployment || n?.deployment || {}) as Record<string, unknown>).mode || 'native', port: ssh.port || 22, auth: ssh.auth_method || 'key', key: ssh.private_key_path || '', keySource:'path',keyContent:'',keyConfigured:!!(ssh.private_key_path_configured||ssh.private_key_path),password: '', override: !!n?.monitor, roots: ((monitor.roots || []) as string[]).join('\n'), extensions: ((monitor.extensions || []) as string[]).join('\n'), excludes: ((monitor.exclude_paths || []) as string[]).join('\n') }) } catch (e) { if(current===dialogVersion&&props.modelValue)error.value = errorMessage(e) } })
function lines(v: string) { return v.split('\n').map(v => v.trim()).filter(Boolean) }
function edit() { const node: Record<string, unknown> = { id: form.id.trim(), name: form.name.trim(), host: form.host.trim(), enabled: form.enabled, deployment: { mode: form.mode }, ssh: { username: 'root', port: Number(form.port), auth_method: form.auth, private_key_path: form.auth==='key'&&form.keySource==='path'?form.key.trim():'', password: form.password } }; if (form.override) node.monitor = { roots: lines(form.roots), extensions: lines(form.extensions), exclude_paths: lines(form.excludes) }; else node.monitor = null; return { revision: settings.value?.revision || '', patch: {}, node_id: props.nodeId, node, ssh_private_key_content:form.auth==='key'&&form.keySource==='content'?form.keyContent:undefined } }
function validateContent(){if(reading.value)throw new Error('私钥文件正在读取，请稍候');if(form.auth==='key'&&form.keySource==='content'&&new TextEncoder().encode(form.keyContent).length>maxPrivateKeyBytes)throw new Error('私钥内容不能超过 64 KiB')}
async function inspect() { if(busy.value)return;busy.value = true; error.value = ''; const current=dialogVersion,draft=draftVersion;try { validateContent();preview.value = undefined;const result = await api<Preview>('/api/settings/preview', 'POST', edit());if(current===dialogVersion&&draft===draftVersion&&props.modelValue)preview.value=result } catch (e) { if(current===dialogVersion&&draft===draftVersion&&props.modelValue)error.value = errorMessage(e) } finally { busy.value = false } }
async function save(deploy: boolean) { if(busy.value)return;busy.value = true; error.value = ''; try { validateContent();if (deploy) { const job = await api<Job>('/api/deployments', 'POST', { request_key: requestKey(), revision: settings.value?.revision, kind: 'add-node', node: form.id, edit: edit() }); emit('update:modelValue', false); emit('saved'); await router.push(`/deployments/${job.id}`) } else { await api('/api/settings', 'PUT', edit()); emit('update:modelValue', false); emit('saved') } } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
function copyRoots() { const defaults = ((settings.value?.values.node_defaults || {}) as Record<string, unknown>).monitor as Record<string, unknown> | undefined; form.roots = ((defaults?.roots || []) as string[]).join('\n'); form.extensions = ((defaults?.extensions || []) as string[]).join('\n'); form.excludes = ((defaults?.exclude_paths || []) as string[]).join('\n') }
</script>
<template><el-dialog :model-value="modelValue" :title="nodeId ? '编辑子服务器' : '添加子服务器'" width="min(720px, 96vw)" @update:model-value="emit('update:modelValue', $event)"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top" :disabled="busy" @input="preview = undefined"><div class="form-grid"><el-form-item label="名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="唯一节点 ID"><el-input v-model="form.id" :disabled="!!nodeId" placeholder="node-example" /></el-form-item><el-form-item label="服务器 IP"><el-input v-model="form.host" :disabled="!!nodeId" /></el-form-item><el-form-item label="SSH 端口（root 用户）"><el-input v-model="form.port" type="number" /></el-form-item></div><el-form-item label="部署方式"><el-select v-model="form.mode" @change="preview = undefined"><el-option label="直接运行 Go（无需 Docker）" value="native" /><el-option label="Docker 单容器" value="docker" /></el-select><small class="muted">切换前备份配置与数据库，保留网站文件、扫描任务和待投递事件。Docker 模式缺少引擎时会在支持的系统自动安装。</small></el-form-item><el-form-item label="启用节点"><el-switch v-model="form.enabled" /><small class="muted">停用只保存配置；到系统设置应用后停止中心采集与告警，节点数据保留。</small></el-form-item><el-form-item label="认证方式"><el-select v-model="form.auth"><el-option label="主服务器私钥" value="key" /><el-option label="SSH 密码" value="password" /></el-select></el-form-item><template v-if="form.auth === 'key'"><el-form-item label="私钥来源"><el-radio-group v-model="form.keySource" @change="keySourceChanged"><el-radio value="path">主服务器路径</el-radio><el-radio value="content">私钥内容</el-radio></el-radio-group></el-form-item><p v-if="form.keyConfigured" class="muted">私钥已配置，留空保留；已有私钥内容不会回显。</p><el-form-item v-if="form.keySource==='path'" label="主服务器私钥绝对路径"><el-input v-model="form.key" placeholder="/root/.ssh/node-example" /></el-form-item><el-form-item v-else label="私钥内容"><div class="private-key-entry" @dragover.prevent @drop.prevent.stop="dropped"><el-input v-model="form.keyContent" data-testid="private-key-content" type="textarea" :rows="6" @input="keyReader.cancel()" autocomplete="off" spellcheck="false" placeholder="拖入私钥文件，或在这里粘贴未加密的 OpenSSH / PEM 私钥" /><div class="private-key-actions"><input ref="fileInput" data-testid="private-key-file" type="file" hidden @change="filesSelected"/><el-button :disabled="busy" @click="fileInput?.click()">选择私钥文件</el-button><span class="muted">{{reading?'正在读取文件…':'每次一个文件，最大 64 KiB；读取后请校验并预览。'}}</span></div></div></el-form-item></template><el-form-item v-else label="SSH 密码（已有密码留空保留）"><el-input v-model="form.password" type="password" autocomplete="new-password" /></el-form-item><el-form-item label="覆盖公共监控配置"><el-switch v-model="form.override" /></el-form-item><div v-if="form.override"><p class="muted">数组覆盖公共值。需要保留公共目录时，先复制再追加。</p><el-button @click="copyRoots">复制公共配置</el-button><el-form-item label="根目录，每行一个"><el-input v-model="form.roots" type="textarea" :rows="3" /></el-form-item><el-form-item label="后缀，每行一个"><el-input v-model="form.extensions" type="textarea" :rows="3" /></el-form-item><el-form-item label="忽略规则，每行一个"><el-input v-model="form.excludes" type="textarea" :rows="3" /></el-form-item></div><p class="muted">SSH 指纹自动记录。部署只处理所选节点；网站历史和其他节点继续保留。</p></el-form><el-alert v-if="preview" :title="`校验通过：${preview.restart ? '需要部署对应服务' : '无需重建'}；范围 ${preview.scope}`" type="success" :closable="false" /><p v-if="preview" class="muted">{{(preview.changes||[]).filter(change=>change.field.endsWith('.ssh.private_key')).map(change=>`私钥：${change.after}`).join('；')}}</p><template #footer><el-button @click="emit('update:modelValue', false)">取消</el-button><el-button :loading="busy" :disabled="reading" @click="inspect">校验并预览</el-button><el-button v-if="preview" :loading="busy" :disabled="reading" @click="save(false)">仅保存</el-button><el-button v-if="preview && form.enabled" type="primary" :loading="busy" :disabled="reading" @click="save(true)">保存并部署</el-button></template></el-dialog></template>

<style scoped>.private-key-entry{width:100%;padding:12px;border:1px dashed var(--el-border-color);border-radius:8px}.private-key-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:10px}</style>
